/**
 * ExperimentsManager - Admin panel for A/B testing experiments
 * Shows experiment list, results dashboard with conversion rates,
 * statistical significance, and time-series charts.
 */

import { useState, useMemo } from "react";
import {
  FlaskConical, Play, Pause, Trophy, BarChart3, Users, MousePointerClick,
  TrendingUp, ChevronDown, ChevronUp, Plus, AlertCircle, CheckCircle
} from "lucide-react";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";

/**
 * Calculate statistical significance using a two-proportion z-test
 * Returns { zScore, pValue, significant (at 95% confidence) }
 */
function calculateSignificance(
  visitorsA: number, conversionsA: number,
  visitorsB: number, conversionsB: number
): { zScore: number; pValue: number; significant: boolean; confidence: number } {
  if (visitorsA === 0 || visitorsB === 0) {
    return { zScore: 0, pValue: 1, significant: false, confidence: 0 };
  }

  const pA = conversionsA / visitorsA;
  const pB = conversionsB / visitorsB;
  const pPool = (conversionsA + conversionsB) / (visitorsA + visitorsB);
  const se = Math.sqrt(pPool * (1 - pPool) * (1 / visitorsA + 1 / visitorsB));

  if (se === 0) return { zScore: 0, pValue: 1, significant: false, confidence: 0 };

  const z = (pB - pA) / se;
  // Approximate two-tailed p-value using normal CDF
  const pValue = 2 * (1 - normalCDF(Math.abs(z)));
  const confidence = (1 - pValue) * 100;

  return {
    zScore: z,
    pValue,
    significant: pValue < 0.05,
    confidence: Math.min(confidence, 99.9),
  };
}

/** Standard normal CDF approximation */
function normalCDF(x: number): number {
  const a1 = 0.254829592;
  const a2 = -0.284496736;
  const a3 = 1.421413741;
  const a4 = -1.453152027;
  const a5 = 1.061405429;
  const p = 0.3275911;
  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x) / Math.sqrt(2);
  const t = 1.0 / (1.0 + p * x);
  const y = 1.0 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return 0.5 * (1.0 + sign * y);
}

interface ExperimentResult {
  assignments: { variant: string; count: number }[];
  conversions: { variant: string; eventType: string; count: number }[];
}

/** Map page paths to friendly display names */
function getPageDisplayName(pagePath: string): string {
  const map: Record<string, string> = {
    '/': 'Homepage (PDP)',
    '/down-feather-pillow': 'Down Feather PDP',
    '/articles/hotel-pillow-secret': 'Hotel Expose Advertorial',
    '/articles/neck-pain-solution': 'Neck Pain Advertorial',
    '/articles/sleep-better-tonight': 'Advertorial Page',
  };
  return map[pagePath] || pagePath;
}

function ExperimentCard({ experiment }: { experiment: any }) {
  const [expanded, setExpanded] = useState(false);
  const [showPageBreakdown, setShowPageBreakdown] = useState(false);

  const { data: results, isLoading: resultsLoading } = trpc.experiments.getResults.useQuery(
    { experimentId: experiment.id },
    { enabled: expanded }
  );

  const { data: pageResults, isLoading: pageResultsLoading } = trpc.experiments.getResultsByPage.useQuery(
    { experimentId: experiment.id },
    { enabled: expanded && showPageBreakdown }
  );

  const updateMutation = trpc.experiments.update.useMutation({
    onSuccess: () => {
      toast.success("Experiment updated");
    },
  });

  const utils = trpc.useUtils();

  const stats = useMemo(() => {
    if (!results) return null;

    const variants = experiment.variants.split(",");
    const variantStats = variants.map((v: string) => {
      const trimmed = v.trim();
      const assignmentRow = results.assignments.find((a) => a.variant === trimmed);
      const conversionRow = results.conversions.find(
        (c) => c.variant === trimmed && c.eventType === "checkout_click"
      );
      const visitors = assignmentRow?.count || 0;
      const conversions = conversionRow?.count || 0;
      const rate = visitors > 0 ? (conversions / visitors) * 100 : 0;
      return { variant: trimmed, visitors, conversions, rate };
    });

    // Calculate significance between first two variants
    let significance = null;
    if (variantStats.length >= 2) {
      significance = calculateSignificance(
        variantStats[0].visitors,
        variantStats[0].conversions,
        variantStats[1].visitors,
        variantStats[1].conversions
      );
    }

    const totalVisitors = variantStats.reduce((sum: number, v: any) => sum + v.visitors, 0);
    const totalConversions = variantStats.reduce((sum: number, v: any) => sum + v.conversions, 0);

    return { variantStats, significance, totalVisitors, totalConversions };
  }, [results, experiment.variants]);

  const handleToggleActive = () => {
    updateMutation.mutate(
      { id: experiment.id, data: { isActive: experiment.isActive ? 0 : 1 } },
      {
        onSuccess: () => {
          utils.experiments.getAll.invalidate();
        },
      }
    );
  };

  const handleDeclareWinner = (variant: string) => {
    if (!confirm(`Declare "${variant}" as the winner? All future visitors will see this variant.`)) return;
    updateMutation.mutate(
      { id: experiment.id, data: { winner: variant, isActive: 0 } },
      {
        onSuccess: () => {
          utils.experiments.getAll.invalidate();
          toast.success(`"${variant}" declared as winner`);
        },
      }
    );
  };

  const isActive = experiment.isActive === 1;
  const hasWinner = !!experiment.winner;

  return (
    <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full px-5 py-4 flex items-center justify-between hover:bg-zinc-50 dark:hover:bg-zinc-800/50 transition-colors"
      >
        <div className="flex items-center gap-3">
          <div
            className={`w-2.5 h-2.5 rounded-full ${
              hasWinner
                ? "bg-amber-500"
                : isActive
                ? "bg-emerald-500 animate-pulse"
                : "bg-zinc-300 dark:bg-zinc-600"
            }`}
          />
          <div className="text-left">
            <h3 className="font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              {experiment.name}
            </h3>
            <p className="text-xs text-zinc-500 dark:text-zinc-400 mt-0.5">
              {experiment.slug} &middot; {experiment.variants.split(",").length} variants
              {hasWinner && (
                <span className="ml-2 text-amber-600 dark:text-amber-400 font-medium">
                  Winner: {experiment.winner}
                </span>
              )}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span
            className={`text-[10px] font-medium px-2 py-0.5 rounded-full ${
              hasWinner
                ? "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400"
                : isActive
                ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
                : "bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-400"
            }`}
          >
            {hasWinner ? "Completed" : isActive ? "Running" : "Paused"}
          </span>
          {expanded ? (
            <ChevronUp className="w-4 h-4 text-zinc-400" />
          ) : (
            <ChevronDown className="w-4 h-4 text-zinc-400" />
          )}
        </div>
      </button>

      {/* Expanded Content */}
      {expanded && (
        <div className="border-t border-zinc-100 dark:border-zinc-800">
          {/* Description */}
          {experiment.description && (
            <div className="px-5 pt-4">
              <p className="text-xs text-zinc-500 dark:text-zinc-400 leading-relaxed">
                {experiment.description}
              </p>
            </div>
          )}

          {/* Controls */}
          <div className="px-5 py-3 flex gap-2">
            {!hasWinner && (
              <button
                onClick={handleToggleActive}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                  isActive
                    ? "bg-amber-50 text-amber-700 hover:bg-amber-100 dark:bg-amber-900/20 dark:text-amber-400"
                    : "bg-emerald-50 text-emerald-700 hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-400"
                }`}
              >
                {isActive ? (
                  <>
                    <Pause className="w-3 h-3" /> Pause
                  </>
                ) : (
                  <>
                    <Play className="w-3 h-3" /> Resume
                  </>
                )}
              </button>
            )}
          </div>

          {/* Results */}
          {resultsLoading ? (
            <div className="px-5 pb-5">
              <div className="animate-pulse space-y-3">
                <div className="h-20 bg-zinc-100 dark:bg-zinc-800 rounded-lg" />
                <div className="h-20 bg-zinc-100 dark:bg-zinc-800 rounded-lg" />
              </div>
            </div>
          ) : stats ? (
            <div className="px-5 pb-5 space-y-4">
              {/* Summary Cards */}
              <div className="grid grid-cols-3 gap-3">
                <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-lg p-3">
                  <div className="flex items-center gap-1.5 mb-1">
                    <Users className="w-3.5 h-3.5 text-zinc-400" />
                    <span className="text-[10px] font-medium text-zinc-500 dark:text-zinc-400 uppercase tracking-wide">
                      Visitors
                    </span>
                  </div>
                  <p className="text-lg font-bold text-zinc-900 dark:text-zinc-100">
                    {stats.totalVisitors.toLocaleString()}
                  </p>
                </div>
                <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-lg p-3">
                  <div className="flex items-center gap-1.5 mb-1">
                    <MousePointerClick className="w-3.5 h-3.5 text-zinc-400" />
                    <span className="text-[10px] font-medium text-zinc-500 dark:text-zinc-400 uppercase tracking-wide">
                      Checkouts
                    </span>
                  </div>
                  <p className="text-lg font-bold text-zinc-900 dark:text-zinc-100">
                    {stats.totalConversions.toLocaleString()}
                  </p>
                </div>
                <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-lg p-3">
                  <div className="flex items-center gap-1.5 mb-1">
                    <TrendingUp className="w-3.5 h-3.5 text-zinc-400" />
                    <span className="text-[10px] font-medium text-zinc-500 dark:text-zinc-400 uppercase tracking-wide">
                      Confidence
                    </span>
                  </div>
                  <p className={`text-lg font-bold ${
                    stats.significance?.significant
                      ? "text-emerald-600 dark:text-emerald-400"
                      : "text-zinc-900 dark:text-zinc-100"
                  }`}>
                    {stats.significance ? `${stats.significance.confidence.toFixed(1)}%` : "N/A"}
                  </p>
                </div>
              </div>

              {/* Significance Banner */}
              {stats.significance && (
                <div
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-xs ${
                    stats.significance.significant
                      ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400"
                      : "bg-zinc-50 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400"
                  }`}
                >
                  {stats.significance.significant ? (
                    <>
                      <CheckCircle className="w-4 h-4 flex-shrink-0" />
                      <span>
                        Statistically significant at 95% confidence (p={stats.significance.pValue.toFixed(4)}).
                        {stats.significance.zScore > 0
                          ? ` "${stats.variantStats[1]?.variant}" outperforms "${stats.variantStats[0]?.variant}".`
                          : ` "${stats.variantStats[0]?.variant}" outperforms "${stats.variantStats[1]?.variant}".`}
                      </span>
                    </>
                  ) : (
                    <>
                      <AlertCircle className="w-4 h-4 flex-shrink-0" />
                      <span>
                        Not yet statistically significant (p={stats.significance.pValue.toFixed(4)}).
                        Need more data to draw conclusions.
                      </span>
                    </>
                  )}
                </div>
              )}

              {/* Variant Breakdown */}
              <div className="space-y-3">
                <h4 className="text-xs font-semibold text-zinc-700 dark:text-zinc-300 uppercase tracking-wide">
                  Variant Breakdown
                </h4>
                {stats.variantStats.map((v: any) => {
                  const isWinner = experiment.winner === v.variant;
                  const maxRate = Math.max(...stats.variantStats.map((s: any) => s.rate));
                  const isLeading = v.rate === maxRate && v.rate > 0;

                  return (
                    <div
                      key={v.variant}
                      className={`rounded-lg border p-4 ${
                        isWinner
                          ? "border-amber-300 bg-amber-50/50 dark:border-amber-700 dark:bg-amber-900/10"
                          : "border-zinc-200 dark:border-zinc-700"
                      }`}
                    >
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
                            {v.variant === "control" ? "Control (With Animation)" : "Variant (No Animation)"}
                          </span>
                          {isWinner && (
                            <span className="flex items-center gap-1 text-[10px] font-medium text-amber-600 dark:text-amber-400 bg-amber-100 dark:bg-amber-900/30 px-1.5 py-0.5 rounded">
                              <Trophy className="w-3 h-3" /> Winner
                            </span>
                          )}
                          {isLeading && !isWinner && (
                            <span className="text-[10px] font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30 px-1.5 py-0.5 rounded">
                              Leading
                            </span>
                          )}
                        </div>
                        {!hasWinner && stats.significance?.significant && isLeading && (
                          <button
                            onClick={() => handleDeclareWinner(v.variant)}
                            className="flex items-center gap-1 px-2.5 py-1 rounded-lg bg-amber-500 hover:bg-amber-600 text-white text-[10px] font-medium transition-colors"
                          >
                            <Trophy className="w-3 h-3" /> Declare Winner
                          </button>
                        )}
                      </div>

                      <div className="grid grid-cols-3 gap-4">
                        <div>
                          <p className="text-[10px] text-zinc-500 dark:text-zinc-400 uppercase tracking-wide mb-0.5">
                            Visitors
                          </p>
                          <p className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                            {v.visitors.toLocaleString()}
                          </p>
                        </div>
                        <div>
                          <p className="text-[10px] text-zinc-500 dark:text-zinc-400 uppercase tracking-wide mb-0.5">
                            Checkouts
                          </p>
                          <p className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                            {v.conversions.toLocaleString()}
                          </p>
                        </div>
                        <div>
                          <p className="text-[10px] text-zinc-500 dark:text-zinc-400 uppercase tracking-wide mb-0.5">
                            Conv. Rate
                          </p>
                          <p className={`text-sm font-semibold ${
                            isLeading && v.rate > 0
                              ? "text-emerald-600 dark:text-emerald-400"
                              : "text-zinc-900 dark:text-zinc-100"
                          }`}>
                            {v.rate.toFixed(2)}%
                          </p>
                        </div>
                      </div>

                      {/* Conversion bar */}
                      <div className="mt-3 h-2 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
                        <div
                          className={`h-full rounded-full transition-all duration-500 ${
                            isWinner
                              ? "bg-amber-500"
                              : isLeading
                              ? "bg-emerald-500"
                              : "bg-indigo-500"
                          }`}
                          style={{ width: `${Math.min(v.rate * 5, 100)}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Page Source Breakdown Toggle */}
              <div>
                <button
                  onClick={() => setShowPageBreakdown(!showPageBreakdown)}
                  className="flex items-center gap-1.5 text-xs font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 transition-colors"
                >
                  {showPageBreakdown ? (
                    <><ChevronUp className="w-3 h-3" /> Hide Page Breakdown</>
                  ) : (
                    <><ChevronDown className="w-3 h-3" /> Show Page Breakdown</>
                  )}
                </button>

                {showPageBreakdown && (
                  <div className="mt-3">
                    {pageResultsLoading ? (
                      <div className="animate-pulse h-24 bg-zinc-100 dark:bg-zinc-800 rounded-lg" />
                    ) : pageResults && pageResults.pages.length > 0 ? (
                      <div className="border border-zinc-200 dark:border-zinc-700 rounded-lg overflow-hidden">
                        <table className="w-full text-xs">
                          <thead>
                            <tr className="bg-zinc-50 dark:bg-zinc-800/70">
                              <th className="text-left px-3 py-2 font-semibold text-zinc-600 dark:text-zinc-300">Page</th>
                              {experiment.variants.split(",").map((v: string) => {
                                const trimmed = v.trim();
                                return (
                                  <th key={`${trimmed}-visitors`} className="text-center px-2 py-2 font-semibold text-zinc-600 dark:text-zinc-300">
                                    {trimmed === "control" ? "Control" : "Variant"}
                                    <br /><span className="font-normal text-zinc-400">Visitors</span>
                                  </th>
                                );
                              })}
                              {experiment.variants.split(",").map((v: string) => {
                                const trimmed = v.trim();
                                return (
                                  <th key={`${trimmed}-rate`} className="text-center px-2 py-2 font-semibold text-zinc-600 dark:text-zinc-300">
                                    {trimmed === "control" ? "Control" : "Variant"}
                                    <br /><span className="font-normal text-zinc-400">Conv. Rate</span>
                                  </th>
                                );
                              })}
                            </tr>
                          </thead>
                          <tbody>
                            {pageResults.pages.map((page) => {
                              const variants = experiment.variants.split(",").map((v: string) => v.trim());
                              const variantData = variants.map((variant: string) => {
                                const assignRow = page.assignments.find(a => a.variant === variant);
                                const convRow = page.conversions.find(c => c.variant === variant && c.eventType === "checkout_click");
                                const visitors = assignRow?.count || 0;
                                const conversions = convRow?.count || 0;
                                const rate = visitors > 0 ? (conversions / visitors) * 100 : 0;
                                return { variant, visitors, conversions, rate };
                              });

                              return (
                                <tr key={page.pagePath} className="border-t border-zinc-100 dark:border-zinc-800 hover:bg-zinc-50/50 dark:hover:bg-zinc-800/30">
                                  <td className="px-3 py-2.5 font-medium text-zinc-800 dark:text-zinc-200">
                                    {getPageDisplayName(page.pagePath)}
                                    <span className="block text-[10px] text-zinc-400 dark:text-zinc-500 font-normal">{page.pagePath}</span>
                                  </td>
                                  {variantData.map((vd: any) => (
                                    <td key={`${vd.variant}-v`} className="text-center px-2 py-2.5 text-zinc-700 dark:text-zinc-300">
                                      {vd.visitors.toLocaleString()}
                                    </td>
                                  ))}
                                  {variantData.map((vd: any) => {
                                    const maxRate = Math.max(...variantData.map((d: any) => d.rate));
                                    const isLeading = vd.rate === maxRate && vd.rate > 0;
                                    return (
                                      <td key={`${vd.variant}-r`} className={`text-center px-2 py-2.5 font-medium ${
                                        isLeading ? "text-emerald-600 dark:text-emerald-400" : "text-zinc-700 dark:text-zinc-300"
                                      }`}>
                                        {vd.rate.toFixed(2)}%
                                        <span className="block text-[10px] font-normal text-zinc-400">
                                          {vd.conversions}/{vd.visitors}
                                        </span>
                                      </td>
                                    );
                                  })}
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    ) : (
                      <p className="text-[10px] text-zinc-400 dark:text-zinc-500 italic">
                        No page-level data available yet.
                      </p>
                    )}
                  </div>
                )}
              </div>

              {/* Minimum sample size note */}
              {stats.totalVisitors < 100 && (
                <p className="text-[10px] text-zinc-400 dark:text-zinc-500 italic">
                  Minimum recommended sample: 100 visitors per variant for reliable results.
                  Currently at {stats.totalVisitors} total visitors.
                </p>
              )}
            </div>
          ) : (
            <div className="px-5 pb-5">
              <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-lg p-6 text-center">
                <BarChart3 className="w-8 h-8 text-zinc-300 dark:text-zinc-600 mx-auto mb-2" />
                <p className="text-xs text-zinc-500 dark:text-zinc-400">
                  No data yet. Results will appear once visitors are assigned.
                </p>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export function ExperimentsManager() {
  const { data: experiments, isLoading } = trpc.experiments.getAll.useQuery();
  const seedMutation = trpc.experiments.seed.useMutation();
  const utils = trpc.useUtils();

  const handleSeed = () => {
    seedMutation.mutate(undefined, {
      onSuccess: () => {
        utils.experiments.getAll.invalidate();
        toast.success("Checkout animation experiment created");
      },
      onError: (err) => {
        toast.error(`Failed to seed: ${err.message}`);
      },
    });
  };

  return (
    <section>
      <div className="flex items-center justify-between mb-5">
        <div>
          <h3 className="text-lg font-bold text-zinc-900 dark:text-zinc-100 flex items-center gap-2">
            <FlaskConical className="w-5 h-5 text-indigo-500" />
            A/B Experiments
          </h3>
          <p className="text-sm text-zinc-500 dark:text-zinc-400 mt-0.5">
            Track and manage conversion experiments. Primary metric: checkout button clicks.
          </p>
        </div>
        {experiments && experiments.length === 0 && (
          <button
            onClick={handleSeed}
            disabled={seedMutation.isPending}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-medium transition-colors disabled:opacity-50"
          >
            <Plus className="w-3.5 h-3.5" />
            {seedMutation.isPending ? "Creating..." : "Create Checkout Test"}
          </button>
        )}
      </div>

      {isLoading ? (
        <div className="space-y-3">
          <div className="animate-pulse h-16 bg-zinc-100 dark:bg-zinc-800 rounded-xl" />
          <div className="animate-pulse h-16 bg-zinc-100 dark:bg-zinc-800 rounded-xl" />
        </div>
      ) : experiments && experiments.length > 0 ? (
        <div className="space-y-3">
          {experiments.map((exp) => (
            <ExperimentCard key={exp.id} experiment={exp} />
          ))}
        </div>
      ) : (
        <div className="bg-zinc-50 dark:bg-zinc-800/50 rounded-xl p-8 text-center">
          <FlaskConical className="w-10 h-10 text-zinc-300 dark:text-zinc-600 mx-auto mb-3" />
          <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-3">
            No experiments yet. Create your first A/B test to start optimizing.
          </p>
          <button
            onClick={handleSeed}
            disabled={seedMutation.isPending}
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium transition-colors disabled:opacity-50"
          >
            <Plus className="w-4 h-4" />
            {seedMutation.isPending ? "Creating..." : "Create Checkout Animation Test"}
          </button>
        </div>
      )}
    </section>
  );
}
